UI:AddSection(T_DASH,"مرحباً بك في S7LE ULTRA v4.0")local DashStatsBanner=UI:AddInfoBanner(T_DASH,"إحصائيات الجلسة المباشرة","جاري قراءة الفريمات والبنج والذاكرة...")UI:AddAction(T_DASH,"تفعيل وضع الأداء الأقصى (One-Click Max FPS)","تطبيق بوست الفريمات + إزالة الضباب + تنظيف الرام فوراً","تشغيل",function(b)Lighting.GlobalShadows=false Lighting.FogEnd=9e9 pcall(function()settings().Rendering.QualityLevel=Enum.QualityLevel.Level01 end)for _,o in ipairs(workspace:GetDescendants())do if o:IsA("BasePart")then o.Material=Enum.Material.SmoothPlastic o.CastShadow=false elseif o:IsA("ParticleEmitter")or o:IsA("Trail")then o.Enabled=false end end collectgarbage("collect")b.Text="مفعّل ✓"Notify("الوضع الأقصى","تم تفعيل حزمة الأداء الشاملة!",3,"success")end)
