UI:AddSection(T_GFX,"التحكم بالإضاءة والأجواء")UI:AddDropdown(T_GFX,"قوالب الأجواء الجاهزة (Atmosphere)",{"الوضع الأصلي (Default)","نهار مشرق (Bright Day)","غروب دافئ (Golden Sunset)","ليل نيون (Cyber Night)","رؤية ليلية كاملة (FullBright)"},"الوضع الأصلي (Default)",function(c)if c=="الوضع الأصلي (Default)"then Lighting.ClockTime=OriginalState.ClockTime Lighting.Brightness=OriginalState.Brightness Lighting.Ambient=OriginalState.Ambient Lighting.GlobalShadows=OriginalState.GlobalShadows elseif c=="نهار مشرق (Bright Day)"then Lighting.ClockTime,Lighting.Brightness=14,2.2 elseif c=="غروب دافئ (Golden Sunset)"then Lighting.ClockTime,Lighting.Brightness=17.8,1.8 elseif c=="ليل نيون (Cyber Night)"then Lighting.ClockTime,Lighting.Brightness=22,1.1 elseif c=="رؤية ليلية كاملة (FullBright)"then Lighting.ClockTime,Lighting.Brightness=14,2.5 Lighting.Ambient=Color3.fromRGB(255,255,255)Lighting.OutdoorAmbient=Color3.fromRGB(255,255,255)Lighting.GlobalShadows=false end Notify("الأجواء","تم تطبيق: "..c,2.5,"success")end)
