local CrosshairEnabled,CrosshairStyle,CrosshairSize=false,"نقطة متوهجة (Dot)",8 local function RebuildCrosshair()local o=ScreenGui:FindFirstChild("S7LE_CrosshairRoot")if o then o:Destroy()end if not CrosshairEnabled then return end local h=Instance.new("Frame")h.Name="S7LE_CrosshairRoot"h.Size=UDim2.new(0,40,0,40)h.Position=UDim2.new(0.5,-20,0.5,-20)h.BackgroundTransparency=1 h.ZIndex=45 h.Parent=ScreenGui if CrosshairStyle=="نقطة متوهجة (Dot)"then local d=Instance.new("Frame")d.Size=UDim2.new(0,CrosshairSize,0,CrosshairSize)d.AnchorPoint=Vector2.new(0.5,0.5)d.Position=UDim2.new(0.5,0,0.5,0)d.BackgroundColor3=Colors.Primary d.Parent=h Instance.new("UICorner",d).CornerRadius=UDim.new(1,0)elseif CrosshairStyle=="صليب احترافي (Cross)"then local hz=Instance.new("Frame")hz.Size=UDim2.new(0,CrosshairSize*2.2,0,2)hz.AnchorPoint=Vector2.new(0.5,0.5)hz.Position=UDim2.new(0.5,0,0.5,0)hz.BackgroundColor3=Colors.Primary hz.BorderSizePixel=0 hz.Parent=h local vt=Instance.new("Frame")vt.Size=UDim2.new(0,2,0,CrosshairSize*2.2)vt.AnchorPoint=Vector2.new(0.5,0.5)vt.Position=UDim2.new(0.5,0,0.5,0)vt.BackgroundColor3=Colors.Primary vt.BorderSizePixel=0 vt.Parent=h else local r=Instance.new("Frame")r.Size=UDim2.new(0,CrosshairSize*2.4,0,CrosshairSize*2.4)r.AnchorPoint=Vector2.new(0.5,0.5)r.Position=UDim2.new(0.5,0,0.5,0)r.BackgroundTransparency=1 r.Parent=h Instance.new("UICorner",r).CornerRadius=UDim.new(1,0)local st=Instance.new("UIStroke")st.Color=Colors.Primary st.Thickness=2 st.Parent=r end end
