UI:AddToggle(T_CAM,"وضع التصوير السينمائي (Cinema Mode)","إخفاء قوائم روبلوكس والشات للتصوير",false,function(on)StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.All,not on)end)UI:AddAction(T_CAM,"إصلاح الكاميرا (Fix Camera)","إعادة ضبط الكاميرا فوراً لشخصيتك","إصلاح",function()Camera.CameraType=Enum.CameraType.Custom if LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")then Camera.CameraSubject=LocalPlayer.Character:FindFirstChildOfClass("Humanoid")end Notify("الكاميرا","تم إصلاح الكاميرا",2,"success")end)
UI:AddSection(T_MOV,"التحكم بالشخصية والمؤثرات المحلية")UI:AddToggle(T_MOV,"تفعيل قفل الماوس (Force ShiftLock)","السماح بتفعيل ShiftLock في أي ماب",false,function(on)LocalPlayer.DevEnableMouseLock=on end)UI:AddToggle(T_MOV,"تثبيت الشخصية في مكانها (Anchor Self)","تجميد موقع شخصيتك لمنع الانزلاق",false,function(on)if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")then LocalPlayer.Character.HumanoidRootPart.Anchored=on end end)UI:AddToggle(T_MOV,"مسار ضوئي خلف الشخصية (Neon Trail)","إضافة خط ضوئي متوهج يتبع حركتك محلياً",false,function(on)local hrp=LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")if not hrp then return end if on and not hrp:FindFirstChild("S7LE_LocalTrail")then local a0=Instance.new("Attachment",hrp)a0.Name="S7LE_A0"a0.Position=Vector3.new(0,1.2,0)local a1=Instance.new("Attachment",hrp)a1.Name="S7LE_A1"a1.Position=Vector3.new(0,-1.2,0)local tr=Instance.new("Trail",hrp)tr.Name="S7LE_LocalTrail"tr.Attachment0=a0 tr.Attachment1=a1 tr.Lifetime=0.6 tr.Color=ColorSequence.new(Colors.Primary,Colors.Secondary)elseif not on then for _,n in ipairs({"S7LE_LocalTrail","S7LE_A0","S7LE_A1"})do local o=hrp:FindFirstChild(n)if o then o:Destroy()end end end end)UI:AddAction(T_MOV,"رسبن سريع (Quick Respawn)","إعادة إحياء شخصيتك فوراً","رسبن",function()if LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")then LocalPlayer.Character:FindFirstChildOfClass("Humanoid").Health=0 end end)
UI:AddSection(T_WAY,"نظام حفظ الإحداثيات (Waypoints)")local SavedWaypoints={Slot1=nil,Slot2=nil}UI:AddAction(T_WAY,"حفظ الموقع في الخانة 1 (Save Slot 1)","تخزين إحداثيات موقعك الحالي","حفظ 1",function(b)if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")then SavedWaypoints.Slot1=LocalPlayer.Character.HumanoidRootPart.CFrame b.Text="محفوظ ✓"Notify("المواقع","تم حفظ الموقع 1",2,"success")end end)UI:AddAction(T_WAY,"الذهاب للموقع المحفوظ 1 (Go Slot 1)","الانتقال للإحداثيات المخزنة في الخانة 1","انتقال 1",function()local hrp=LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")if hrp and SavedWaypoints.Slot1 then hrp.CFrame=SavedWaypoints.Slot1 end end)UI:AddAction(T_WAY,"نسخ إحداثيات موقعك (Copy XYZ)","نسخ إحداثيات X, Y, Z للحافظة","نسخ",function()if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")and setclipboard then local p=LocalPlayer.Character.HumanoidRootPart.Position setclipboard(string.format("%.2f, %.2f, %.2f",p.X,p.Y,p.Z))Notify("الحافظة","تم نسخ إحداثياتك",2,"success")end end)
UI:AddSection(T_VIS,"المؤشرات البصرية للاعبين")local PlayerHighlightActive=false local function SyncHighlights()for _,p in ipairs(Players:GetPlayers())do if p~=LocalPlayer and p.Character then local hl=p.Character:FindFirstChild("S7LE_PlayerGlow")if PlayerHighlightActive and not hl then hl=Instance.new("Highlight",p.Character)hl.Name="S7LE_PlayerGlow"hl.FillColor=Colors.Primary hl.OutlineColor=Color3.fromRGB(255,255,255)hl.FillTransparency=0.65 elseif not PlayerHighlightActive and hl then hl:Destroy()end end end end UI:AddToggle(T_VIS,"هالة ضوئية حول اللاعبين (Highlight)","إظهار إطار مضيء حول اللاعبين لتمييز مواقعهم",false,function(on)PlayerHighlightActive=on SyncHighlights()end)
UI:AddSection(T_PLR,"مستكشف اللاعبين في السيرفر")local SelectedPlayerName=LocalPlayer.Name local PlrNames={}for _,p in ipairs(Players:GetPlayers())do table.insert(PlrNames,p.Name)end UI:AddDropdown(T_PLR,"اختر لاعباً للفحص",PlrNames,LocalPlayer.Name,function(c)SelectedPlayerName=c local t=Players:FindFirstChild(c)if t then Notify("فحص اللاعب",string.format("%s | عمر الحساب: %d يوم | ID: %d",t.DisplayName,t.AccountAge or 0,t.UserId),3.5,"success")end end)UI:AddToggle(T_PLR,"مراقبة اللاعب بالكاميرا (Spectate)","توجيه الكاميرا لمشاهدة اللاعب المختار",false,function(on)local t=Players:FindFirstChild(SelectedPlayerName)if on and t and t.Character and t.Character:FindFirstChildOfClass("Humanoid")then Camera.CameraSubject=t.Character:FindFirstChildOfClass("Humanoid")elseif LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")then Camera.CameraSubject=LocalPlayer.Character:FindFirstChildOfClass("Humanoid")end end)
UI:AddSection(T_AUD,"الصوتيات والأدوات الذكية")local AntiAFKActive=true UI:AddToggle(T_AUD,"مانع الطرد التلقائي (Anti-AFK)","يمنع السيرفر من طردك عند ترك الجهاز",true,function(on)AntiAFKActive=on end)UI:AddToggle(T_AUD,"كتم صوت اللعبة (Mute Game)","إيقاف جميع الأصوات بالماب",false,function(on)for _,s in ipairs(workspace:GetDescendants())do if s:IsA("Sound")then s.Volume=on and 0 or 0.5 end end end)UI:AddSlider(T_AUD,"مستوى صوت الماب",0,100,50,"%",function(v)for _,s in ipairs(workspace:GetDescendants())do if s:IsA("Sound")then s.Volume=v/100 end end end)UI:AddToggle(T_AUD,"إخفاء فقاعات الشات","إخفاء الرسائل فوق رؤوس اللاعبين",false,function(on)pcall(function()ChatService.BubbleChatEnabled=not on end)end)
UI:AddSection(T_SRV,"التنقل بين السيرفرات والشبكة")UI:AddAction(T_SRV,"إعادة دخول (Rejoin)","إعادة الاتصال بنفس السيرفر الحالي","دخول",function()TeleportService:TeleportToPlaceInstance(game.PlaceId,game.JobId,LocalPlayer)end)UI:AddAction(T_SRV,"سيرفر قليل اللاعبين (Low Server)","الانتقال لأخف سيرفر لرفع الفريمات","بحث",function()pcall(function()local u="https://games.roblox.com/v1/games/"..game.PlaceId.."/servers/Public?sortOrder=Asc&limit=100"local d=HttpService:JSONDecode(game:HttpGet(u))for _,s in ipairs(d.data)do if s.playing<s.maxPlayers and s.id~=game.JobId then TeleportService:TeleportToPlaceInstance(game.PlaceId,s.id,LocalPlayer)break end end end)end)UI:AddAction(T_SRV,"تغيير السيرفر (Server Hop)","الانتقال لأي سيرفر عام آخر","انتقال",function()TeleportService:Teleport(game.PlaceId,LocalPlayer)end)UI:AddAction(T_SRV,"نسخ معرف السيرفر (Copy JobId)","نسخ JobId لمشاركته مع أصدقائك","نسخ",function()if setclipboard then setclipboard(game.JobId)Notify("الحافظة","تم نسخ JobId",2,"success")end end)
UI:AddSection(T_SET,"تخصيص المظهر والإعدادات")local function ApplyThemeByIndex(ix)local t=ThemeCatalog[ix]if not t then return end ActiveThemeIndex=ix for k,v in pairs(t)do Colors[k]=v end VFXEngine:Tween(MainWindow,0.3,{BackgroundColor3=Colors.Base})VFXEngine:Tween(Sidebar,0.3,{BackgroundColor3=Colors.Sidebar})VFXEngine:Tween(HudBar,0.3,{BackgroundColor3=Colors.Base})VFXEngine:Tween(HudStroke,0.3,{Color=Colors.Primary})VFXEngine:Tween(HudLogo,0.3,{TextColor3=Colors.Primary})VFXEngine:Tween(RestorePill,0.3,{BackgroundColor3=Colors.Base})VFXEngine:Tween(RestoreStroke,0.3,{Color=Colors.Primary})VFXEngine:Tween(BrandSubtitle,0.3,{TextColor3=Colors.Primary})VFXEngine:Tween(KeyHint,0.3,{TextColor3=Colors.Primary})VFXEngine:Tween(AmbientShadow,0.3,{ImageColor3=Colors.Primary})WindowBorderGrad.Color=ColorSequence.new({ColorSequenceKeypoint.new(0,Colors.Primary),ColorSequenceKeypoint.new(1,Colors.Secondary)})HudGrad.Color=ColorSequence.new({ColorSequenceKeypoint.new(0,Colors.Primary),ColorSequenceKeypoint.new(1,Colors.Secondary)})BrandLogoGrad.Color=ColorSequence.new({ColorSequenceKeypoint.new(0,Color3.fromRGB(255,255,255)),ColorSequenceKeypoint.new(1,Colors.Primary)})for n,td in pairs(UI.Tabs)do td.grad.Color=ColorSequence.new({ColorSequenceKeypoint.new(0,Colors.Primary),ColorSequenceKeypoint.new(1,Colors.Secondary)})if UI.ActiveTab~=n then td.btn.BackgroundColor3=Colors.Card td.btn.TextColor3=Colors.SubText end end for _,it in ipairs(UI.AllCards)do if it.card and it.card:IsA("Frame")then it.card.BackgroundColor3=Colors.Card end end if CrosshairEnabled then RebuildCrosshair()end Notify("المظهر","تم تطبيق ثيم: "..t.Name,2.5,"success")end
local ThemeNames={}for _,t in ipairs(ThemeCatalog)do table.insert(ThemeNames,t.Name)end UI:AddDropdown(T_SET,"اختيار ثيم الواجهة (7 Themes)",ThemeNames,ThemeNames[1],function(s)for i,t in ipairs(ThemeCatalog)do if t.Name==s then ApplyThemeByIndex(i)break end end end)UI:AddAction(T_SET,"تبديل سريع للثيم التالي","التنقل السريع بين جميع الثيمات","تبديل",function()ApplyThemeByIndex((ActiveThemeIndex%#ThemeCatalog)+1)end)UI:AddSlider(T_SET,"سرعة الأنيميشن (Animation Speed)",50,200,100,"%",function(v)VFXEngine.AnimationSpeed=v/100 end)UI:AddToggle(T_SET,"مؤثرات الشرار (Sparkle VFX)","تفعيل جزيئات الضوء عند الضغط",true,function(on)VFXEngine.ParticlesEnabled=on end)UI:AddToggle(T_SET,"مؤثر التموج (Ripple VFX)","تفعيل دوائر التموج داخل الأزرار",true,function(on)VFXEngine.RipplesEnabled=on end)UI:AddToggle(T_SET,"أصوات الواجهة (UI Sounds)","تشغيل أو كتم أصوات النقرات",true,function(on)VFXEngine.SoundEnabled=on end)UI:AddToggle(T_SET,"شريط الأداء العلوي (HUD)","إظهار أو إخفاء شريط الفريمات",true,function(on)HudBar.Visible=on end)UI:AddToggle(T_SET,"الإشعارات المنبثقة","تفعيل أو إيقاف الإشعارات",true,function(on)NotificationsEnabled=on end)UI:AddAction(T_SET,"ريسيت شامل لكل شيء (Factory Reset)","إرجاع جميع الخيارات لوضعها الأصلي","ريسيت",function(b)for _,fn in ipairs(Lifecycle.ResetCallbacks)do pcall(fn)end Lighting.GlobalShadows=OriginalState.GlobalShadows Lighting.Brightness=OriginalState.Brightness Lighting.ClockTime=OriginalState.ClockTime Lighting.FogEnd=OriginalState.FogEnd Camera.FieldOfView=OriginalState.FieldOfView LocalPlayer.CameraMaxZoomDistance=OriginalState.MaxZoom StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.All,true)b.Text="تم ✓"Notify("النظام","تم عمل ريسيت شامل",2.5,"success")task.wait(1.2)b.Text="ريسيت"end)UI:AddAction(T_SET,"إغلاق السكربت نهائياً","حذف الواجهة وتنظيف الذاكرة","إغلاق",function()Lifecycle:DestroyAll()end)
Lifecycle:TrackConnection(LocalPlayer.Idled:Connect(function()if AntiAFKActive then VirtualUser:CaptureController()VirtualUser:ClickButton2(Vector2.new())end end))Lifecycle:TrackConnection(UserInputService.InputBegan:Connect(function(i,gp)if gp then return end if i.KeyCode==Enum.KeyCode.RightControl then ToggleMainWindow(not WindowOpen)elseif ZoomKeyEnabled and i.KeyCode==Enum.KeyCode.Z then VFXEngine:Tween(Camera,0.22,{FieldOfView=26})end end))Lifecycle:TrackConnection(UserInputService.InputEnded:Connect(function(i)if ZoomKeyEnabled and i.KeyCode==Enum.KeyCode.Z then VFXEngine:Tween(Camera,0.22,{FieldOfView=BaseCameraFOV})end end))Lifecycle:TrackConnection(SearchBox:GetPropertyChangedSignal("Text"):Connect(function()local q=string.lower(SearchBox.Text)if q==""then for _,it in ipairs(UI.AllCards)do it.card.Parent=it.page it.card.Visible=true end for n,pd in pairs(UI.Pages)do pd.frame.Visible=(n==UI.ActiveTab)end return end for _,pd in pairs(UI.Pages)do pd.frame.Visible=false end local rp=UI.Pages[T_DASH].frame rp.Visible=true for _,it in ipairs(UI.AllCards)do if string.find(it.key,q,1,true)then it.card.Parent=rp it.card.Visible=true else it.card.Visible=false end end end))
local frames,lastCheck=0,os.clock()Lifecycle:TrackConnection(RunService.RenderStepped:Connect(function()frames=frames+1 local now=os.clock()if now-lastCheck>=1 then local p,m=0,0 pcall(function()p=math.floor(Stats.Network.ServerStatsItem["Data Ping"]:GetValue())end)pcall(function()m=math.floor(Stats:GetTotalMemoryUsageMb())end)local df=math.floor(now-SessionStart)local mn,sc=math.floor(df/60),df%60 local pc=#Players:GetPlayers()local fc=frames>=55 and"#00EB96"or(frames>=30 and"#FFC341"or"#F54B5F")HudText.Text=string.format('FPS: <font color="%s">%d</font>  |  Ping: %dms  |  RAM: %dMB  |  Players: %d  |  %02d:%02d',fc,frames,p,m,pc,mn,sc)DashStatsBanner.Text=string.format("الفريمات: %d FPS  |  البنج: %d ms  |  الذاكرة: %d MB  |  اللاعبين: %d/%d",frames,p,m,pc,Players.MaxPlayers)frames=0 lastCheck=now end end))Notify("S7LE ULTRA v4.0","تم تحميل الواجهة المحدثة بالكامل!",3.5,"success")
local S7LE_Utils={}function S7LE_Utils.FormatTime(s)s=math.max(0,math.floor(s))local h=math.floor(s/3600)local m=math.floor((s%3600)/60)local sc=s%60 if h>0 then return string.format("%02d:%02d:%02d",h,m,sc)end return string.format("%02d:%02d",m,sc)end function S7LE_Utils.CountWorkspaceObjects()local p,l,pt,sn=0,0,0,0 for _,o in ipairs(workspace:GetDescendants())do if o:IsA("BasePart")then p=p+1 elseif o:IsA("Light")then l=l+1 elseif o:IsA("ParticleEmitter")or o:IsA("Trail")then pt=pt+1 elseif o:IsA("Sound")then sn=sn+1 end end return{Parts=p,Lights=l,Particles=pt,Sounds=sn}end
UI:AddAction(T_DASH,"إحصاء عناصر الماب بالتفصيل (Workspace Scan)","حساب عدد المجسمات والإضاءات والجزيئات بالماب","فحص الماب",function()local d=S7LE_Utils.CountWorkspaceObjects()Notify("فحص الماب",string.format("مجسمات: %d | إضاءات: %d | جزيئات: %d | أصوات: %d",d.Parts,d.Lights,d.Particles,d.Sounds),4,"success")end)UI:AddAction(T_DASH,"تشخيص النظام والاتصال (Diagnostics)","فحص الفريمات والذاكرة وبنج السيرفر الحالي","تشخيص",function()local p,m=0,0 pcall(function()p=math.floor(Stats.Network.ServerStatsItem["Data Ping"]:GetValue())end)pcall(function()m=math.floor(Stats:GetTotalMemoryUsageMb())end)Notify("تقرير التشخيص",string.format("البنج: %d ms | استهلاك الذاكرة: %d MB | عناصر الماب: %d",p,m,#workspace:GetDescendants()),4,"success")end)
UI:AddSection(T_CAM,"قوالب الكاميرا والفلاتر السينمائية")UI:AddDropdown(T_CAM,"قالب زاوية الرؤية (FOV Presets)",{"افتراضي (70° Default)","واسع تنافسي (90° Pro)","عريض جداً (110° Ultra Wide)","زوم تصويري (50° Cinematic)"},"افتراضي (70° Default)",function(pr)local tf=70 if pr=="واسع تنافسي (90° Pro)"then tf=90 elseif pr=="عريض جداً (110° Ultra Wide)"then tf=110 elseif pr=="زوم تصويري (50° Cinematic)"then tf=50 end BaseCameraFOV=tf VFXEngine:Tween(Camera,0.35,{FieldOfView=tf},Enum.EasingStyle.Quint)Notify("الكاميرا","تم ضبط زاوية الرؤية إلى "..tf.."°",2,"success")end)UI:AddDropdown(T_GFX,"فلتر الألوان السينمائي (Color Grading)",{"بدون فلتر (None)","سينمائي بارد (Cool Cinema)","دافئ ذهبي (Warm Gold)","تباين عالي (High Contrast)","أبيض وأسود (Noir B&W)"},"بدون فلتر (None)",function(fn)local ex=Lighting:FindFirstChild("S7LE_ColorFilter")if ex then ex:Destroy()end if fn=="بدون فلتر (None)"then Notify("الفلاتر","تمت إزالة فلتر الشاشة")return end local cc=Instance.new("ColorCorrectionEffect")cc.Name="S7LE_ColorFilter"cc.Parent=Lighting if fn=="سينمائي بارد (Cool Cinema)"then cc.TintColor=Color3.fromRGB(220,240,255)cc.Contrast,cc.Saturation=0.12,0.15 elseif fn=="دافئ ذهبي (Warm Gold)"then cc.TintColor=Color3.fromRGB(255,240,215)cc.Contrast,cc.Saturation=0.1,0.2 elseif fn=="تباين عالي (High Contrast)"then cc.Contrast,cc.Saturation=0.28,0.22 elseif fn=="أبيض وأسود (Noir B&W)"then cc.Saturation,cc.Contrast=-1,0.2 end Notify("الفلاتر","تم تطبيق فلتر: "..fn,2.5,"success")end)UI:AddToggle(T_GFX,"إشراقة الشمس (SunRays Effect)","إضافة أشعة شمس واقعية في السماء",false,function(on)local ry=Lighting:FindFirstChild("S7LE_SunRays")if on and not ry then ry=Instance.new("SunRaysEffect",Lighting)ry.Name="S7LE_SunRays"ry.Intensity=0.15 elseif not on and ry then ry:Destroy()end Notify("أشعة الشمس",on and"تم تفعيل أشعة الشمس"or"تم إيقاف أشعة الشمس")end)
UI:AddSection(T_SET,"اختصارات لوحة المفاتيح السريعة")UI:AddKeybind(T_SET,"اختصار بوست الفريمات السريع","اضغط الزر لتفعيل بوست الفريمات في أي وقت",Enum.KeyCode.F6,function()Lighting.GlobalShadows=false Lighting.FogEnd=9e9 collectgarbage("collect")Notify("اختصار سريع","تم تفعيل بوست الفريمات السريع!",2,"success")end)UI:AddKeybind(T_SET,"اختصار إصلاح الكاميرا","اضغط الزر لإعادة ضبط الكاميرا فوراً",Enum.KeyCode.F7,function()Camera.CameraType=Enum.CameraType.Custom if LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")then Camera.CameraSubject=LocalPlayer.Character:FindFirstChildOfClass("Humanoid")end Notify("اختصار سريع","تم إصلاح الكاميرا!",2,"success")end)UI:AddKeybind(T_SET,"اختصار إخفاء/إظهار الواجهة","زر سريع لفتح وإغلاق قائمة S7LE",Enum.KeyCode.Insert,function()ToggleMainWindow(not WindowOpen)end)print("[S7LE ULTRA v4.0] All modules and extensions loaded successfully. Rights: s7le")
